cypress_script:
describe('Frames Page Navigation', () => {
  it('should navigate to Nested Frames', () => {
    cy.visit('https://the-internet.herokuapp.com/frames');
    cy.get('a').contains('Nested Frames').click();
    cy.url().should('include', '/nested_frames');
    cy.get('#page-footer').should('be.visible');
  });
  it('should not navigate on invalid link click', () => {
    cy.visit('https://the-internet.herokuapp.com/frames');
    cy.get('a').contains('iFrame').click();
    cy.url().should('include', '/iframe');
    cy.get('#content').should('be.visible');
    cy.get('#page-footer').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Frames Page Navigation', () => {
  test('should navigate to Nested Frames', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/frames');
    await page.click('text=Nested Frames');
    await expect(page).toHaveURL(/.*nested_frames/);
    await expect(page.locator('#page-footer')).toBeVisible();
  });
  test('should not navigate on invalid link click', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/frames');
    await page.click('text=iFrame');
    await expect(page).toHaveURL(/.*iframe/);
    await expect(page.locator('#content')).toBeVisible();
    await expect(page.locator('#page-footer')).toBeVisible();
  });
});
